export function bossClearedGroundGeometryPresentation(input, reducedFlash = false) { const alpha = Math.max(0, Math.min(.2, input.alpha)) * (reducedFlash ? .58 : 1), radius = Math.max(24, input.radius), angle = Number.isFinite(input.angle) ? input.angle : 0, length = Number.isFinite(input.length) ? input.length : 0; const shape = input.geometryShape === 'corridor' ? 'corridor' : input.geometryShape === 'cross' ? 'cross' : 'circle'; const halfLength = shape === 'circle' ? 0 : Math.min(240, Math.max(radius * 1.35, length * .5)); const halfWidth = shape === 'circle' ? 0 : Math.max(14, Math.min(54, radius * .52)); return { shape, alpha, radius, angle, halfLength, halfWidth, presentationOnly: true }; }
